import {kickOutcomes} from './kick-outcomes.js';

const copy={
 en:{kicker:'KICK OUTCOMES / OBSERVED',title:'How often did it work?',swipe:'Swipe for shots →',pass:'Passes to a teammate',target:'Shots on target',goal:'Goals from shots',waitPass:'No completed pass attempt yet',waitShot:'No completed shot attempt yet',sample:'Small sample · not a prediction',explain:'What counts?',definition:'A pass succeeds when a teammate receives it. A shot is on target if it is saved or scores. Goal rate counts goals divided by shots. These percentages describe only completed synthetic events through this moment; they are not chances of the next kick succeeding.',team:{harbor:'Harbor FC',north:'Northbridge',neutral:'Both teams'},made:(n,d)=>`${n} of ${d} recorded attempts`},
 es:{kicker:'RESULTADOS DE LOS GOLPES / OBSERVADOS',title:'¿Cuántas veces funcionó?',swipe:'Desliza para ver tiros →',pass:'Pases a un compañero',target:'Tiros a puerta',goal:'Goles por tiro',waitPass:'Aún no hay pases completos',waitShot:'Aún no hay tiros completos',sample:'Muestra pequeña · no es predicción',explain:'¿Qué cuenta?',definition:'Un pase llega a un compañero. Un tiro va a puerta si el portero lo detiene o entra. La tasa de gol es goles divididos entre tiros. Los porcentajes describen solo eventos sintéticos terminados hasta este momento.',team:{harbor:'Harbor FC',north:'Northbridge',neutral:'Ambos equipos'},made:(n,d)=>`${n} de ${d} intentos registrados`},
 pt:{kicker:'RESULTADOS DOS CHUTES / OBSERVADOS',title:'Quantas vezes funcionou?',swipe:'Deslize para ver chutes →',pass:'Passes a um colega',target:'Chutes no alvo',goal:'Gols por chute',waitPass:'Ainda não há passe concluído',waitShot:'Ainda não há chute concluído',sample:'Amostra pequena · não é previsão',explain:'O que conta?',definition:'Um passe chega a um colega. Um chute vai no alvo se for defendido ou virar gol. A taxa de gol é gols divididos pelos chutes. Os percentuais descrevem somente eventos sintéticos concluídos até este momento.',team:{harbor:'Harbor FC',north:'Northbridge',neutral:'Ambos os times'},made:(n,d)=>`${n} de ${d} tentativas registradas`}
};
export function createKickOutcomesView(){
 const root=document.createElement('section');root.className='kick-outcomes';root.hidden=true;root.setAttribute('aria-label','Observed kick outcomes');
 root.innerHTML='<div class="kick-outcomes-heading"><div><span class="kick-outcomes-kicker"></span><h2></h2></div><div class="kick-outcomes-context"><strong></strong><time></time></div></div><div class="kick-outcomes-swipe"></div><div class="kick-outcomes-cards"></div><details><summary></summary><p></p></details>';
 // Keep these three plain-language rates above the optional deep-dive drawer.
 (document.querySelector('#centre .understand-deep-dive')||document.querySelector('#centre .formation-layout')).before(root);
 const cards=[];for(let i=0;i<3;i++){const card=document.createElement('article');card.className='kick-outcome';card.innerHTML='<span class="kick-outcome-label"></span><div class="kick-outcome-value"><strong></strong><span></span></div><div class="kick-outcome-track"><i></i></div><p></p><small></small>';root.querySelector('.kick-outcomes-cards').append(card);cards.push(card);}
 return {hide(){root.hidden=true;},render(state,session,clock){
  root.hidden=false;
  const boundary=document.querySelector('#centre .understand-evidence-boundary');if(boundary&&root.previousElementSibling!==boundary)boundary.after(root);
  const c=copy[session.language]||copy.en,data=kickOutcomes(state.seen,session.team),kinds=[data.passes,data.onTarget,data.goals],labels=[c.pass,c.target,c.goal];
  root.querySelector('.kick-outcomes-kicker').textContent=c.kicker;root.querySelector('h2').textContent=c.title;root.querySelector('.kick-outcomes-swipe').textContent=c.swipe;root.querySelector('.kick-outcomes-context strong').textContent=c.team[session.team];root.querySelector('time').textContent=clock;root.querySelector('summary').textContent=c.explain;root.querySelector('details p').textContent=c.definition;
  cards.forEach((card,i)=>{const item=kinds[i];card.querySelector('.kick-outcome-label').textContent=labels[i];card.querySelector('strong').textContent=item.percent===null?'—':`${item.percent}%`;card.querySelector('.kick-outcome-value span').textContent=item.percent===null?'waiting':'observed';card.querySelector('.kick-outcome-track i').style.width=`${item.percent??0}%`;card.querySelector('p').textContent=item.attempted?c.made(item.made,item.attempted):i===0?c.waitPass:c.waitShot;card.querySelector('small').textContent=item.attempted&&item.attempted<10?c.sample:'';card.dataset.empty=String(item.percent===null);});
 }};
}
